#include <vector>

using namespace std;

class Solution {
public:
    vector<int> sumEvenAfterQueries(vector<int>& A, vector<vector<int>>& queries) {
        int sum = 0;
        for (int a : A)
            if (a % 2 == 0) sum += a;

        vector<int> res;
        for (auto& q : queries) {
            int val = q[0], i = q[1];
            if (A[i] % 2 == 0) sum -= A[i];
            A[i] += val;
            if (A[i] % 2 == 0) sum += A[i];
            res.push_back(sum);
        }
        return res;
    }
};
